      type(c_ptr),value :: y
      integer(kind(rocsparse_sptrsv_stage_analysis)),value :: sptrsv_stage
      integer(c_size_t),value :: buffer_size_in_bytes
      type(c_ptr),value :: buffer
      type(c_ptr) :: p_error
    end function

