      use iso_c_binding
      import
      implicit none
      integer(kind(rocsparse_status_success)) :: rocsparse_shybmv_
      type(c_ptr),value :: handle
      integer(kind(rocsparse_operation_none)),value :: trans
      real(c_float) :: alpha
      type(c_ptr),value :: descr
      type(c_ptr),value :: hyb
      type(c_ptr),value :: x
      real(c_float) :: beta
